#!/bin/sh
# Write src/version.rs from git. Run this before copying the tree to the Pi.
# The generated file is gitignored, so creating it does not itself mark the tree dirty.
set -eu
cd "$(dirname "$0")"

if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  echo "version.sh: this directory is not a git checkout" >&2
  exit 1
fi

version=$(git describe --tags --always)
if [ -n "$(git status --porcelain)" ]; then
  dirty=true
  label="${version}-dirty"
else
  dirty=false
  label=$version
fi

rust_escape() {
  printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g'
}

version_esc=$(rust_escape "$version")

cat > src/version.rs <<EOF
// Generated by ./version.sh. Do not edit.
pub const VERSION: &str = "${version_esc}";
pub const DIRTY: bool = ${dirty};

pub fn label() -> String {
    if DIRTY {
        format!("{VERSION}-dirty")
    } else {
        VERSION.to_string()
    }
}
EOF

echo "src/version.rs: ${label}"
